import glob, json

for path in sorted(glob.glob("/app/samples/*.json")):
    with open(path) as f:
        doc = json.load(f)
    for r in doc["records"]:
        amt = r["amount"]
        # print any interesting amounts (less than 1, ending with 0, etc.)
        parts = amt.replace("-", "").split(".")
        if len(parts) > 1:
            if parts[0] == "0" or parts[1].endswith("0"):
                print(path, r["currency"], amt)
'

